import type { DesignContent } from "@/lib/design-content";

export const content: DesignContent = {"slug": "home", "title": "UniShare", "css": "\n:root{--teal:#0f6b63;--ink:#171c1b;--muted:#4b5552;--line:#111;--ph:#e4ebe8}\n*{box-sizing:border-box;margin:0;padding:0}\nbody{font-family:\"DM Sans\",system-ui,sans-serif;color:var(--ink);background:#fff;line-height:1.5;padding:env(safe-area-inset-top,0) 0 env(safe-area-inset-bottom,0)}\n.wrap{max-width:860px;margin:0 auto;padding:0 24px}\na{text-decoration:none;color:inherit}\n.btn{display:inline-block;padding:11px 20px;border-radius:6px;font-size:15px;font-weight:500;border:1.5px solid var(--teal);background:var(--teal);color:#fff;cursor:pointer;white-space:nowrap}\n.btn.ghost{background:#fff;color:var(--teal)}\n.btn.sm{padding:8px 14px;font-size:14px}\n.ph{position:relative;background:var(--ph);display:flex;align-items:flex-end;justify-content:flex-start;overflow:hidden}\n.ph img,.arch img{position:absolute;inset:0;width:100%;height:100%;object-fit:cover;display:block}\n.arch img{position:static;height:100%}\n.ph span,.pill{position:absolute;left:8px;bottom:8px;background:#fff;border:1.5px solid var(--line);border-radius:999px;padding:2px 10px;font-size:12px;font-weight:500}\n.ph.big span{display:none}\n.ph.big::after{content:\"Photo\";position:absolute;inset:0;display:flex;align-items:center;justify-content:center;color:var(--muted);font-size:14px}\n\nheader{border-bottom:1.5px solid var(--line)}\nheader .wrap{display:flex;justify-content:space-between;align-items:center;height:64px}\n.logo{display:flex;align-items:center;gap:8px;font-weight:700;font-size:18px}\n.logo svg{stroke:var(--teal)}\nnav{display:flex;align-items:center;gap:22px;font-size:14px}\nnav a.link{color:var(--teal)}\n\n.hero{padding:72px 0 64px}\n.hero .wrap{display:grid;grid-template-columns:1fr 1fr;gap:40px;align-items:center}\nh1{font-size:50px;line-height:1.05;font-weight:700;letter-spacing:-.02em}\nh1 em{font-style:normal;color:var(--teal)}\n.lead{color:var(--muted);font-size:16px;margin:20px 0 26px;max-width:380px}\n.actions{display:flex;gap:10px}\n.note{font-size:12px;color:var(--muted);margin-top:16px}\n.arch{overflow:hidden;aspect-ratio:4/5;border:1.5px solid var(--line);border-radius:200px 200px 10px 10px;box-shadow:10px 10px 0 var(--teal);margin-right:10px}\n\n.features{display:grid;grid-template-columns:1fr 1fr;border-top:1.5px solid var(--line);border-bottom:1.5px solid var(--line)}\n.features>div{padding:56px 40px}\n.features>div:first-child{border-right:1.5px solid var(--line)}\n.col{max-width:380px}\n.features>div:first-child .col{margin-left:auto}\n.features h2,.steps h2{font-size:24px;font-weight:700;letter-spacing:-.01em}\n.features p,.steps .intro{color:var(--muted);font-size:14px;margin-top:8px;max-width:360px}\n.tiles{display:grid;grid-template-columns:repeat(3,1fr);gap:10px;margin-top:28px}\n.tiles .ph{aspect-ratio:1/1.05;border:1.5px solid var(--line);border-radius:8px}\n.rides{display:grid;grid-template-columns:1fr 1fr;gap:10px;margin-top:28px}\n.rides .ph{aspect-ratio:3/4;border:1.5px solid var(--line);border-radius:8px}\n\n.steps{padding:72px 0 80px}\n.steps-head{display:flex;justify-content:space-between;align-items:flex-end;gap:24px;flex-wrap:wrap}\n.steps-head h2{font-size:28px}\n.steps-head .intro{max-width:300px;margin:0;font-size:14px}\n.cards{display:grid;grid-template-columns:repeat(3,1fr);border:1.5px solid var(--line);border-radius:10px;box-shadow:8px 8px 0 var(--teal);margin-top:32px;overflow:hidden}\n.card{padding:22px 20px 24px}\n.card+.card{border-left:1.5px solid var(--line)}\n.card-top{display:flex;justify-content:space-between;align-items:center;margin-bottom:22px}\n.num{width:26px;height:26px;border-radius:50%;background:var(--teal);color:#fff;display:flex;align-items:center;justify-content:center;font-size:13px;font-weight:700}\n.card svg{stroke:var(--teal);width:22px;height:22px;fill:none;stroke-width:1.6}\n.card h3{font-size:16px;font-weight:700;margin-bottom:8px}\n.card p{font-size:13px;color:var(--muted)}\n\n.cta{border-top:1.5px solid var(--line);padding:64px 0 60px}\n.cta .wrap{display:flex;justify-content:space-between;align-items:center;gap:24px;flex-wrap:wrap}\n.cta h2{font-size:30px;line-height:1.15;font-weight:700;letter-spacing:-.01em}\n.cta .actions{gap:10px}\n\nfooter{border-top:1.5px solid var(--line);padding:20px 0;font-size:12px;color:var(--muted)}\n\n@media (max-width:720px){\n  h1{font-size:38px}\n  .hero .wrap,.features,.cards{grid-template-columns:1fr}\n  .hero{padding:48px 0}\n  .arch{margin:0 10px 0 0;max-width:340px;width:100%}\n  .features>div:first-child{border-right:none;border-bottom:1.5px solid var(--line)}\n  .features>div{padding:40px 24px}\n  .features>div:first-child .col{margin-left:0}\n  .card+.card{border-left:none;border-top:1.5px solid var(--line)}\n  .steps-head h2{font-size:24px}\n}\n", "body": "\n\n<header>\n  <div class=\"wrap\">\n    <a class=\"logo\" href=\"/\">\n      <svg width=\"20\" height=\"20\" viewBox=\"0 0 24 24\" fill=\"none\" stroke-width=\"2\"><circle cx=\"8\" cy=\"12\" r=\"5\"/><circle cx=\"16\" cy=\"12\" r=\"5\"/></svg>\n      UniShare\n    </a>\n    <nav>\n      <a class=\"link\" href=\"/log-in\">Log in</a>\n      <a class=\"btn sm\" href=\"/create-account\">Create account</a>\n    </nav>\n  </div>\n</header>\n\n<section class=\"hero\">\n  <div class=\"wrap\">\n    <div>\n      <h1>Your campus,<br>one big <em>shared</em><br><em>shelf.</em></h1>\n      <p class=\"lead\">Rent cameras, calculators, laptops and more from students of your own university. Verified with your university email, never open to outsiders.</p>\n      <div class=\"actions\">\n        <a class=\"btn\" href=\"/create-account\">Create account</a>\n        <a class=\"btn ghost\" href=\"/log-in\">Log in</a>\n      </div>\n      <p class=\"note\">Only students with a university email can join.</p>\n    </div>\n    <div class=\"arch\"><img src=\"data:image/jpeg;base64,\" alt=\"Student holding a shared item\"></div>\n  </div>\n</section>\n\n<section class=\"features\">\n  <div>\n    <div class=\"col\">\n      <h2>Rent what you need for a day</h2>\n      <p>Borrow a calculator for an exam, a charger when yours gives up, or a football for the weekend, all from a student on your campus.</p>\n      <div class=\"tiles\">\n        <div class=\"ph\"><img src=\"data:image/jpeg;base64,\" alt=\"Football\"><span>Football</span></div>\n        <div class=\"ph\"><img src=\"data:image/jpeg;base64,\" alt=\"Laptop charger\"><span>Laptop charger</span></div>\n        <div class=\"ph\"><img src=\"data:image/jpeg;base64,\" alt=\"Earphones\"><span>Earphones</span></div>\n        <div class=\"ph\"><img src=\"data:image/jpeg;base64,\" alt=\"Phone charger\"><span>Phone charger</span></div>\n        <div class=\"ph\"><img src=\"data:image/jpeg;base64,\" alt=\"AirPods\"><span>AirPods</span></div>\n        <div class=\"ph\"><img src=\"data:image/jpeg;base64,\" alt=\"Calculator\"><span>Calculator</span></div>\n      </div>\n    </div>\n  </div>\n  <div>\n    <div class=\"col\">\n      <h2>Share a ride to campus</h2>\n      <p>Heading the same way? Offer a seat or find a ride with someone from your own university, by car or by rickshaw.</p>\n      <div class=\"rides\">\n        <div class=\"ph\"><img src=\"data:image/jpeg;base64,\" alt=\"Car ride\"><span>Car ride</span></div>\n        <div class=\"ph\"><img src=\"data:image/jpeg;base64,\" alt=\"Rickshaw\"><span>Rickshaw</span></div>\n      </div>\n    </div>\n  </div>\n</section>\n\n<section class=\"steps\">\n  <div class=\"wrap\">\n    <div class=\"steps-head\">\n      <h2>Joining takes three moves</h2>\n      <p class=\"intro\">Every member is checked, so you always know the person on the other side is a real student.</p>\n    </div>\n    <div class=\"cards\">\n      <div class=\"card\">\n        <div class=\"card-top\">\n          <span class=\"num\">1</span>\n          <svg viewBox=\"0 0 24 24\"><rect x=\"3\" y=\"5\" width=\"18\" height=\"14\" rx=\"1.5\"/><path d=\"M3 6l9 7 9-7\"/></svg>\n        </div>\n        <h3>Sign up with your university email</h3>\n        <p>We send a 6-digit code to confirm the address is yours.</p>\n      </div>\n      <div class=\"card\">\n        <div class=\"card-top\">\n          <span class=\"num\">2</span>\n          <svg viewBox=\"0 0 24 24\"><rect x=\"2.5\" y=\"5\" width=\"19\" height=\"14\" rx=\"1.5\"/><circle cx=\"8.5\" cy=\"10.5\" r=\"2\"/><path d=\"M5.5 16c.6-1.6 1.6-2.4 3-2.4s2.4.8 3 2.4M14 10h5M14 14h4\"/></svg>\n        </div>\n        <h3>Get verified</h3>\n        <p>Add your student details, ID card and a face photo for review.</p>\n      </div>\n      <div class=\"card\">\n        <div class=\"card-top\">\n          <span class=\"num\">3</span>\n          <svg viewBox=\"0 0 24 24\"><circle cx=\"8\" cy=\"12\" r=\"5\"/><circle cx=\"16\" cy=\"12\" r=\"5\"/></svg>\n        </div>\n        <h3>Rent or lend</h3>\n        <p>Once approved, you only see items and rides from your own university.</p>\n      </div>\n    </div>\n  </div>\n</section>\n\n<section class=\"cta\">\n  <div class=\"wrap\">\n    <h2>Ready to see what your<br>campus has on the shelf?</h2>\n    <div class=\"actions\">\n      <a class=\"btn\" href=\"/create-account\">Create account</a>\n      <a class=\"btn ghost\" href=\"/log-in\">Log in</a>\n    </div>\n  </div>\n</section>\n\n<footer>\n  <div class=\"wrap\">UniShare. Made for university students in Bangladesh.</div>\n</footer>\n\n", "scripts": [], "fonts": ["https://fonts.googleapis.com/css2?family=DM+Sans:wght@400;500;700&display=swap"]};

export default content;
